// Gabungkan hasil 3 node pencarian, beri label brand dan stempel waktu
const keywords = {
  'NF Academy': ['nf academy', 'nurul fikri'],
  'BISA AI': ['bisa ai'],
  'Vinix 7': ['vinix']
};

const getOrganicData = (nodeName) => {
  try {
    const results = $(nodeName).all();
    return results[0].json.organic || [];
  } catch (e) {
    return []; // jika node gagal, kembalikan array kosong agar workflow tidak berhenti
  }
};

const currentTime = DateTime.now().setZone('Asia/Jakarta').toFormat('yyyy-MM-dd HH:mm');

const build = (nodeName, brand) => getOrganicData(nodeName).map(i => {
  const text = ((i.title || '') + ' ' + (i.snippet || '')).toLowerCase();
  const relevant = keywords[brand].some(k => text.includes(k));
  return { json: { ...i, brand: brand, relevant: relevant, processedAt: currentTime } };
});

return [
  ...build('NFA', 'NF Academy'),
  ...build('BISA AI', 'BISA AI'),
  ...build('Vinix7', 'Vinix 7'),
];

// Hitung mention, Share of Voice (SoV), dan susun teks gabungan untuk AI
const allItems = $input.all();

// Mention = hasil pencarian yang benar-benar menyebut nama brand
const relevantItems = allItems.filter(i => i.json.relevant);
const total = relevantItems.length;

const countBrand = (b) => relevantItems.filter(i => i.json.brand === b).length;
const counts = {
  nfa: countBrand('NF Academy'),
  bisa: countBrand('BISA AI'),
  vinix: countBrand('Vinix 7'),
};

const pct = (n) => total > 0 ? ((n / total) * 100).toFixed(1) : '0.0';
const sov = {
  nfa: pct(counts.nfa),
  bisa: pct(counts.bisa),
  vinix: pct(counts.vinix),
};

const textOf = (b) => allItems
  .filter(i => i.json.brand === b)
  .map(i => '- ' + (i.json.title || '') + ': ' + (i.json.snippet || ''))
  .join('\n');

const combinedText =
  '=== NF Academy ===\n' + textOf('NF Academy') + '\n\n' +
  '=== BISA AI ===\n' + textOf('BISA AI') + '\n\n' +
  '=== Vinix 7 ===\n' + textOf('Vinix 7');

return [{
  json: {
    metrics: { total_mentions: total, breakdown: counts, share_of_voice: sov },
    combinedText: combinedText,
    processedAt: allItems.length ? allItems[0].json.processedAt : ''
  }
}];

