// Susun laporan HTML dari metrik + hasil analisis AI
const m = $('Menyiapkan Teks AI').first().json;
const raw = $json.text || $json.output || '';

let ai = null;
try {
  const clean = String(raw).replace(/```json|```/g, '').trim();
  const s = clean.indexOf('{');
  const e = clean.lastIndexOf('}');
  ai = JSON.parse(clean.slice(s, e + 1));
} catch (err) {
  ai = null;
}

const esc = (t) => String(t === undefined || t === null ? '' : t)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const brands = [
  { key: 'nfa', name: 'NF Academy', color: '#f26b21' },
  { key: 'bisa', name: 'BISA AI', color: '#2f6fd6' },
  { key: 'vinix', name: 'Vinix 7', color: '#16a085' },
];

const tanggal = m.processedAt || DateTime.now().setZone('Asia/Jakarta').toFormat('yyyy-MM-dd HH:mm');
const ringkasan = ai && ai.ringkasan_eksekutif ? ai.ringkasan_eksekutif : String(raw).slice(0, 1500);
const rekomendasi = ai && Array.isArray(ai.rekomendasi) ? ai.rekomendasi : [];

const rows = brands.map(b => {
  const d = ai && ai.brand && ai.brand[b.key] ? ai.brand[b.key] : {};
  return '<tr>' +
    '<td><b>' + b.name + '</b></td>' +
    '<td class="c">' + m.metrics.breakdown[b.key] + '</td>' +
    '<td class="c">' + m.metrics.share_of_voice[b.key] + '%</td>' +
    '<td class="c"><b>' + esc(d.skor !== undefined ? d.skor : '-') + '/10</b></td>' +
    '<td class="c">' + esc(d.sentimen || '-') + '</td>' +
    '<td>' + esc(d.alasan || '-') + '</td>' +
    '</tr>';
}).join('');

const bars = brands.map(b =>
  '<div class="bar-row"><div class="bar-label">' + b.name + '</div>' +
  '<div class="bar-track"><div class="bar-fill" style="width:' + m.metrics.share_of_voice[b.key] + '%;background:' + b.color + '"></div></div>' +
  '<div class="bar-val">' + m.metrics.share_of_voice[b.key] + '%</div></div>'
).join('');

const recoHtml = rekomendasi.map(r => '<li>' + esc(r) + '</li>').join('');

const html = '<!DOCTYPE html><html><head><meta charset="UTF-8"><style>' +
  'body{font-family:Arial,Helvetica,sans-serif;color:#222;margin:0;padding:32px;font-size:13px}' +
  'h1{color:#1f3a6e;margin:0 0 4px;font-size:24px}' +
  'h2{color:#1f3a6e;border-bottom:2px solid #f26b21;padding-bottom:4px;margin-top:26px;font-size:16px}' +
  '.sub{color:#666;margin-bottom:18px}' +
  '.box{background:#f4f7fc;border-left:4px solid #1f3a6e;padding:12px 14px;line-height:1.55}' +
  'table{width:100%;border-collapse:collapse;margin-top:8px}' +
  'th{background:#1f3a6e;color:#fff;padding:8px;text-align:left}' +
  'td{border:1px solid #d5dbe6;padding:8px;vertical-align:top}' +
  '.c{text-align:center}' +
  '.bar-row{display:flex;align-items:center;margin:8px 0}' +
  '.bar-label{width:110px;font-weight:bold}' +
  '.bar-track{flex:1;background:#e6eaf2;height:18px;border-radius:9px;overflow:hidden}' +
  '.bar-fill{height:18px}' +
  '.bar-val{width:60px;text-align:right;font-weight:bold}' +
  'li{margin-bottom:6px;line-height:1.5}' +
  '.foot{margin-top:28px;color:#888;font-size:11px}' +
  '</style></head><body>' +
  '<h1>Laporan Competitor Monitoring</h1>' +
  '<div class="sub">NF Academy vs BISA AI vs Vinix 7 | Diproses: ' + esc(tanggal) + ' WIB</div>' +
  '<h2>Ringkasan Eksekutif</h2><div class="box">' + esc(ringkasan) + '</div>' +
  '<h2>Share of Voice</h2>' +
  '<div>Total mention: <b>' + m.metrics.total_mentions + '</b></div>' + bars +
  '<h2>Tabel Perbandingan</h2>' +
  '<table><tr><th>Brand</th><th>Mention</th><th>SoV</th><th>Skor Reputasi</th><th>Sentimen</th><th>Alasan</th></tr>' + rows + '</table>' +
  '<h2>Rekomendasi Strategis</h2><ul>' + (recoHtml || '<li>-</li>') + '</ul>' +
  '<div class="foot">Dihasilkan otomatis oleh workflow n8n (Serper API, OpenRouter, PDFShift).</div>' +
  '</body></html>';

return [{ json: { html: html, processedAt: tanggal } }];
